import cyclopts

app = cyclopts.App(name="myapp")


@app.command
def start():
    """Start the service."""
    print("starting...")


@app.command
def stop():
    """Stop the service."""
    print("stopping...")


@app.default
def status():
    """Show the current status (runs when no subcommand is given)."""
    print("status: idle")


if __name__ == "__main__":
    app()
